HELPER_CC = '    def _r14_operand_negated(self, reg):\n        # [R14-04] 区域作为布尔操作数时的极性：该操作数的「真值边」指向本区域的\n        # merge_block（而不是 then 体）即为负极性。链式比较操作数的极性记在\n        # **末段** 的跳转上（头段末指令是 IF_FALSE->清理块），故先用既有\n        # _detect_chained_compare_pattern 取末段再判。只读同层块事实。\n        cb = getattr(reg, "condition_block", None) or getattr(reg, "entry", None)\n        if cb is None:\n            return False\n        segs = [cb]\n        try:\n            if self.region_analyzer._is_chained_compare_header(cb):\n                _info = self.region_analyzer._detect_chained_compare_pattern(cb)\n                if _info and _info.get("extra_chain_blocks"):\n                    segs = [cb] + list(_info["extra_chain_blocks"])\n        except Exception:\n            return False\n        _li = segs[-1].get_last_instruction()\n        if _li is None or getattr(_li, "argval", None) is None:\n            return False\n        if "TRUE" not in _li.opname and "NOT_NONE" not in _li.opname:\n            return False\n        _tgt = self.cfg.get_block_by_offset(_li.argval) if isinstance(_li.argval, int) else None\n        return _tgt is not None and _tgt is getattr(reg, "merge_block", None) \\\n            and bool(getattr(reg, "then_blocks", None))\n\n'
